    const cityCenter = cityCoordinates[city] || cityCoordinates['Mazatlán'];
    const latitude = station === 'Urbi Villa' ? 23.2231986 : cityCenter[0] + (((index % 7) - 3) * .0081);
    const longitude = station === 'Urbi Villa' ? -106.3733595 : cityCenter[1] + (((index % 5) - 2) * .0092);
    if (station === 'Urbi Villa') return [local,station,city,'Disponible',128.05,14000,14,localPhotos[index % localPhotos.length],mapsUrl,latitude,longitude];
    const monthsVacant = Math.max(1, Math.round((24 + ((index * 13) % 168)) / 30));
    return [local,station,city,statuses[index % statuses.length],72 + ((index * 17) % 149),18500 + ((index * 3700) % 41000),monthsVacant,localPhotos[index % localPhotos.length],mapsUrl,latitude,longitude];
